function safeAreaColor(value) {
  return typeof value === 'string' && /^#[0-9a-f]{6}$/i.test(value) ? value : '#8dbb8c';
}
function readStore(key, fallback) {
  try {
    const raw = window.mpAccountStorage.getItem(key);
    const value = raw === null ? fallback : JSON.parse(raw);
    if (Array.isArray(fallback)) {
      if (!Array.isArray(value)) return fallback;
      if (key === 'mp_areas') return value.filter(item => item &&
        typeof item.name === 'string' && ['string','number'].includes(typeof item.id) &&
        Number.isFinite(Number(item.goal)) && Number(item.goal) > 0);
      if (key === 'mp_entries' || key === 'mp_journal') return value.filter(item => item &&
        typeof item.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(item.date) &&
        ['string','number'].includes(typeof item.id) &&
        (key !== 'mp_entries' || Number.isFinite(Number(item.value))));
      return value;
    }
    if (fallback && typeof fallback === 'object') {
      if (!value || typeof value !== 'object' || Array.isArray(value)) return fallback;
      if (key === 'mp_care') return {
        ...fallback, ...value,
        checkins: Array.isArray(value.checkins) ? value.checkins.filter(item => item && typeof item.date === 'string') : [],
        goals: Array.isArray(value.goals) ? value.goals.filter(item => item && typeof item.date === 'string') : [],
        reminder: { ...fallback.reminder, ...value.reminder,
          days: Array.isArray(value.reminder?.days) ? value.reminder.days : undefined }
      };
    }
    return value;
  } catch { return fallback; }
}
