const ideas={cansado:['Escolha só uma coisa que deixaria o próximo momento um pouco mais fácil. Pode ser beber água, abrir a janela ou descansar por cinco minutos.','Se hoje está pesado, reduza a meta: faça uma tarefa por dois minutos e depois decida se quer continuar.','Uma pausa também conta. Se puder, coma algo, tome água ou mande uma mensagem para alguém de confiança.'],ansioso:['Apoie os pés no chão e nomeie cinco coisas que consegue ver. Depois escolha apenas o próximo passo, sem tentar resolver tudo agora.','Experimente soltar o ar devagar algumas vezes, sem forçar a respiração. Se isso não ajudar, pare e escolha outra forma de se sentir seguro.','Anote o que está preocupando você e marque uma coisa pequena que pode esperar até mais tarde.'],desanimado:['Escolha uma ação muito pequena: lavar o rosto, trocar de roupa ou sair da cama por alguns minutos. Pequeno já é válido.','Tente se aproximar de alguém seguro, mesmo que seja só enviar “não estou muito bem, pode conversar comigo?”.','Se esse desânimo vem persistindo, conversar com uma UBS ou profissional de saúde pode ser um primeiro passo.'],bem:['Registre uma coisa que funcionou hoje e pense em como facilitar para repeti-la.','Aproveite a energia para uma atividade que importa para você, sem transformar isso numa obrigação.','Reconheça o que você já fez. Se quiser, escolha uma meta pequena para amanhã.']};document.getElementById('newTip').addEventListener('click',()=>{const moodMap={bem:'bem','mais-ou-menos':'bem',ansioso:'ansioso',triste:'desanimado',cansado:'cansado'},check=careState.checkins.find(x=>x.date===iso(new Date())),mood=check?moodMap[check.mood]:document.getElementById('moodSelect').value,list=ideas[mood]||ideas.bem;let tip=list[Math.floor(Math.random()*list.length)],goal=careState.goals.find(g=>g.date===iso(new Date())&&!g.done);if(goal)tip+=` Se isso combinar com seu momento, sua meta pequena de hoje é: ${goal.text}.`;document.getElementById('suggestion').textContent=tip});
function showNearbyLinks(region){const q=region.trim();if(!q)return;const maps=(term)=>`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(term+' perto de '+q)}`;document.getElementById('nearbyLinks').innerHTML=`<a href="${maps('CAPS saúde mental')}" target="_blank" rel="noopener noreferrer">Buscar CAPS no mapa ↗</a><a href="${maps('UBS unidade básica de saúde')}" target="_blank" rel="noopener noreferrer">Buscar UBS no mapa ↗</a>`;document.getElementById('nearbyLinks').hidden=false;document.getElementById('locationStatus').textContent=`Busca preparada para: ${q}. O mapa pode mostrar endereço e telefone do serviço.`}
