document.getElementById('deleteData').addEventListener('click',async()=>{if(!await confirmAction('Os dados deste navegador e, se você estiver conectado, os dados da conta serão apagados e não poderão ser recuperados.'))return;const status=document.getElementById('privacyStatus'),button=document.getElementById('deleteData');button.disabled=true;status.textContent='Apagando seus dados…';try{if(authClient&&currentUser){for(const table of ['progress_entries','progress_areas','journal_entries','care_profiles','push_subscriptions','push_delivery_log']){const {error}=await authClient.from(table).delete().eq('user_id',currentUser.id);if(error)throw error}for(const bucketName of ['community-photos','community-profile-media']){for(;;){const {data:files,error}=await authClient.storage.from(bucketName).list(currentUser.id,{limit:100,offset:0});if(error)throw error;if(!files?.length)break;const paths=files.map(file=>currentUser.id+'/'+file.name);const {error:removeError}=await authClient.storage.from(bucketName).remove(paths);if(removeError)throw removeError;if(files.length<100)break}}for(const [table,column] of [['community_posts','user_id'],['community_profiles','user_id'],['community_reports','reporter_id']]){const {error}=await authClient.from(table).delete().eq(column,currentUser.id);if(error)throw error}}areas=[];entries=[];journalItems=[];careState={checkins:[],goals:[],reminder:{enabled:false,time:'20:00'}};for(const key of ['mp_areas','mp_entries','mp_journal','mp_care','mp_community_profile','mp_social_demo_v1','mp_reminded','mp_push_active'])window.mpAccountStorage.removeItem(key);save();render();renderJournal();renderCare();status.textContent=currentUser?'Dados apagados do navegador e da conta.':'Dados apagados deste navegador.'}catch(error){console.error('Exclusão de dados incompleta:',error);status.textContent='Não consegui concluir toda a exclusão. Alguns dados podem já ter sido apagados; verifique a conexão e tente novamente.'}finally{button.disabled=false}});
function saveJournalLocal(){try{window.mpAccountStorage.setItem('mp_journal',JSON.stringify(journalItems));return true}catch{return false}}
function renderJournal(){const box=document.getElementById('journalEntries');if(!box)return;const sorted=[...journalItems].sort((a,b)=>b.date.localeCompare(a.date));box.innerHTML=sorted.length?sorted.map(j=>`<article class="journal-entry"><small>${fmtDate(j.date)}</small><h3>${esc(j.title||'Meu dia')}</h3><p>${esc(j.text)}</p>${j.response?`<div class="journal-response"><strong>Resposta da IA</strong><br>${esc(j.response)}</div>`:''}<div class="journal-entry-actions"><button type="button" data-journal-edit="${esc(j.id)}">Editar</button><button type="button" data-journal-delete="${esc(j.id)}">Excluir</button></div></article>`).join(''):'<div class="empty">Suas anotações aparecerão aqui.</div>'}
async function saveJournalCloud(item){if(!authClient||!currentUser)return false;const {error}=await authClient.from('journal_entries').upsert({id:item.id,user_id:currentUser.id,entry_date:item.date,title:item.title||'',body:item.text,response:item.response||''});if(error){console.error(error);return false}return true}
document.getElementById('journalDate').value=iso(new Date());
document.getElementById('journalAsk').addEventListener('click',()=>{journalAskNext=true;document.getElementById('journalForm').requestSubmit()});
document.getElementById('journalForm').addEventListener('submit',async e=>{e.preventDefault();if(!document.getElementById('journalStorageConsent').checked){document.getElementById('journalStatus').textContent='Marque a autorização para guardar esta anotação.';return}const ask=journalAskNext;journalAskNext=false;const status=document.getElementById('journalStatus'),response=document.getElementById('journalResponse'),date=document.getElementById('journalDate').value,textValue=document.getElementById('journalText').value.trim();if(!textValue){status.textContent='Escreva um pouco sobre o seu dia antes de guardar.';return}let item=journalItems.find(x=>x.date===date)||{id:uuid(),date,response:''};item={...item,title:document.getElementById('journalTitle').value.trim(),text:textValue,date};const at=journalItems.findIndex(x=>x.id===item.id);if(at>=0)journalItems[at]=item;else journalItems.push(item);saveJournalLocal();renderJournal();if(currentUser){const ok=await saveJournalCloud(item);if(!ok){status.textContent='Anotação guardada neste navegador, mas não sincronizada com a conta.';return}}status.textContent=currentUser?'Anotação guardada na sua conta.':'Anotação guardada neste navegador. Entre para sincronizar entre dispositivos.';if(!ask){toast('Dia guardado no diário.');return}if(!document.getElementById('journalConsent').checked){status.textContent='Para pedir uma resposta, marque primeiro a autorização de envio do texto à IA.';return}if(!currentUser||!authClient){status.textContent='Para usar a resposta de IA, conecte o login do Supabase e a função segura seguindo CONFIGURAR_LOGIN.md. Sua anotação continua salva.';return}const askButton=document.getElementById('journalAsk');askButton.disabled=true;status.textContent='Preparando uma resposta acolhedora…';try{const {data,error}=await authClient.functions.invoke('journal-response',{body:{text:textValue,style:document.getElementById('journalStyle').value}});if(error)throw error;item.response=String(data?.response||'');const idx=journalItems.findIndex(x=>x.id===item.id);if(idx>=0)journalItems[idx]=item;saveJournalLocal();await saveJournalCloud(item);response.textContent=item.response;response.hidden=false;renderJournal();status.textContent='Resposta recebida. Ela é uma reflexão geral, não atendimento profissional.'}catch(error){let apiCode='';try{const details=await error?.context?.clone?.().json();apiCode=details?.code||details?.error_code||''}catch{}status.textContent=apiCode==='credit_balance_exhausted'?'A conta da API de IA está sem créditos. Sua anotação continua salva; tente novamente depois de adicionar saldo.':apiCode==='ai_rate_limited'?'Você chegou ao limite diário de 10 respostas. Tente novamente amanhã.':apiCode==='quota_unavailable'?'O limite diário da IA está indisponível. Tente novamente mais tarde.':'Não consegui obter a resposta agora. Sua anotação continua salva; tente novamente mais tarde.';console.error('Falha na resposta de IA:',error)}finally{askButton.disabled=false}});
document.getElementById('journalEntries').addEventListener('click',async e=>{const edit=e.target.closest('[data-journal-edit]'),del=e.target.closest('[data-journal-delete]');if(edit){const item=journalItems.find(x=>x.id===edit.dataset.journalEdit);if(item){document.getElementById('journalDate').value=item.date;document.getElementById('journalTitle').value=item.title||'';document.getElementById('journalText').value=item.text;document.getElementById('journalResponse').textContent=item.response||'';document.getElementById('journalResponse').hidden=!item.response;document.getElementById('journalForm').scrollIntoView({behavior:'smooth',block:'start'})}}if(del){const id=del.dataset.journalDelete;if(await confirmAction('Tem certeza que deseja excluir esta anotação do diário?')){if(authClient&&currentUser){const {error}=await authClient.from('journal_entries').delete().eq('id',id).eq('user_id',currentUser.id);if(error){document.getElementById('journalStatus').textContent='Não consegui excluir da nuvem. A anotação continua salva.';return}}journalItems=journalItems.filter(x=>x.id!==id);saveJournalLocal();renderJournal()}}});
async function mergeLocalProgress(user,remoteAreaRows,remoteEntryRows){const remoteAreaIds=new Set(remoteAreaRows.map(a=>String(a.id))),remoteEntriesById=new Map(remoteEntryRows.map(e=>[String(e.id),e])),idMap=new Map(),newAreas=[];for(const area of areas){const localId=String(area.id);if(remoteAreaIds.has(localId)){idMap.set(localId,localId);continue}if(remoteAreaRows.length){const matchingArea=remoteAreaRows.find(remote=>remote.name===area.name);if(matchingArea){idMap.set(localId,String(matchingArea.id));continue}if(!/^[0-9a-f-]{36}$/i.test(localId))continue}const cloudId=/^[0-9a-f-]{36}$/i.test(localId)?localId:uuid(),copy={...area,id:cloudId};idMap.set(localId,cloudId);newAreas.push(copy)}if(newAreas.length){const {error}=await authClient.from('progress_areas').upsert(newAreas.map(a=>({id:a.id,user_id:user.id,name:a.name,icon:a.icon,color:a.color,goal:a.goal})));if(error)throw error}const localEntries=entries.map(e=>({...e,id:/^[0-9a-f-]{36}$/i.test(String(e.id))?String(e.id):uuid(),areaId:idMap.get(String(e.areaId))})).filter(e=>e.areaId),entriesToSync=localEntries.filter(e=>{const remote=remoteEntriesById.get(String(e.id));return !remote||remote.area_id!==e.areaId||remote.title!==e.title||remote.note!==(e.note||'')||Number(remote.points)!==Number(e.value)||remote.entry_date!==e.date});if(entriesToSync.length){const {error}=await authClient.from('progress_entries').upsert(entriesToSync.map(e=>({id:e.id,user_id:user.id,area_id:e.areaId,title:e.title,note:e.note||'',points:e.value,entry_date:e.date})));if(error)throw error}const localById=new Map(localEntries.map(e=>[String(e.id),e]));areas=[...remoteAreaRows.map(a=>({id:a.id,name:a.name,icon:a.icon,color:a.color,goal:a.goal})),...newAreas];entries=[...remoteEntryRows.map(e=>localById.get(String(e.id))||({id:e.id,areaId:e.area_id,title:e.title,note:e.note||'',value:e.points,date:e.entry_date})),...localEntries.filter(e=>!remoteEntriesById.has(String(e.id)))];save()}
async function loadCloudProgress(user){setAuthMessage('Carregando seu progresso…');const [areaResult,entryResult,journalResult,careResult]=await Promise.all([authClient.from('progress_areas').select('*').eq('user_id',user.id).order('created_at'),authClient.from('progress_entries').select('*').eq('user_id',user.id).order('entry_date',{ascending:false}),authClient.from('journal_entries').select('*').eq('user_id',user.id).order('entry_date',{ascending:false}),authClient.from('care_profiles').select('state').eq('user_id',user.id).maybeSingle()]);if(areaResult.error||entryResult.error){const err=areaResult.error||entryResult.error;setAuthMessage('Não consegui carregar os dados. Confira se executou o arquivo SQL de configuração: '+err.message,true);return}if(journalResult.error)console.error('Diário não sincronizado:',journalResult.error.message);if(careResult.error)console.error('Dados de cuidado não sincronizados:',careResult.error.message);let diaryNeedsSync=false;try{await mergeLocalProgress(user,areaResult.data||[],entryResult.data||[])}catch(error){setAuthMessage('Sua conta entrou, mas não consegui mesclar os dados locais: '+error.message,true);return}if(!journalResult.error){const remoteJournal=(journalResult.data||[]).map(j=>({id:j.id,date:j.entry_date,title:j.title||'',text:j.body,response:j.response||''})),remoteById=new Map(remoteJournal.map(j=>[String(j.id),j])),localById=new Map(journalItems.map(j=>[String(j.id),j])),journalToSync=journalItems.filter(j=>{const remote=remoteById.get(String(j.id));return !remote||remote.date!==j.date||remote.title!==j.title||remote.text!==j.text||remote.response!==j.response});if(journalToSync.length){const {error}=await authClient.from('journal_entries').upsert(journalToSync.map(j=>({id:j.id,user_id:user.id,entry_date:j.date,title:j.title||'',body:j.text,response:j.response||''})));if(error){console.error('Diário local não sincronizado:',error.message);diaryNeedsSync=true}}journalItems=[...remoteJournal.map(j=>localById.get(String(j.id))||j),...journalItems.filter(j=>!remoteById.has(String(j.id)))];saveJournalLocal()}if(!careResult.error){if(careResult.data?.state)careState=careResult.data.state;else await authClient.from('care_profiles').upsert({user_id:user.id,state:careState});window.mpAccountStorage.setItem('mp_care',JSON.stringify(careState))}save();render();renderJournal();renderCare();authModal.classList.remove('open');setAuthMessage(diaryNeedsSync?'Progresso sincronizado. Algumas anotações do diário continuam apenas neste navegador.':'Progresso sincronizado com sua conta.',diaryNeedsSync);if(typeof loadCommunityProfile==='function')void loadCommunityProfile()}
async function acceptSession(session){if(session?.user){if(currentUser?.id===session.user.id)return;currentUser=session.user;setAccountButton();await loadCloudProgress(currentUser)}else if(currentUser){currentUser=null;setAccountButton();if(typeof resetCommunityProfileForSignedOut==='function')resetCommunityProfileForSignedOut();areas=seedAreas.map(a=>({...a}));entries=[];journalItems=[];careState={checkins:[],goals:[],reminder:{enabled:false,time:'20:00'}};for(const key of ['mp_areas','mp_entries','mp_journal','mp_care'])window.mpAccountStorage.removeItem(key);render();renderJournal();renderCare()}}
